# Validation checks
print(f"Total new articles to insert: {len(articles_to_add)}")
for idx, art in enumerate(articles_to_add):
    full_content = "\n\n".join(art["content"])
    char_count = len(full_content)
    print(f"[{idx+1}/9] {art['categoryId']} | {char_count} chars | {art['title'][:60]}...")
    assert char_count >= 2000, f"Article {art['id']} has only {char_count} chars!"

# Read existing articles.ts
path = "src/data/articles.ts"
with open(path, "r", encoding="utf-8") as f:
    text = f.read()

# Locate Mark Rossini article
target_str = '"id": "art-mark-rossini-acceptance-filing-puerto-rico-case-2026"'
assert target_str in text, "Could not find Mark Rossini article in articles.ts!"

# Locate target insertion point before Jim Jordan
jordan_marker = '{\n    "id": "art-2026-11-18-jim-jordan'
insertion_point = text.find(jordan_marker)
assert insertion_point != -1, "Could not find Jim Jordan article"

# Format the 9 articles as JSON-like TypeScript objects
articles_ts_parts = []
for art in articles_to_add:
    # dump each article to formatted JSON with 2-space indentation
    art_json = json.dumps(art, indent=2, ensure_ascii=False)
    # indent each line by 2 spaces to match existing file structure
    indented = "\n".join("  " + line for line in art_json.split("\n"))
    articles_ts_parts.append(indented)

new_articles_block = ",\n".join(articles_ts_parts) + ",\n  "

# Insert into text
new_text = text[:insertion_point] + new_articles_block + text[insertion_point:]

with open(path, "w", encoding="utf-8") as f:
    f.write(new_text)

print(f"Successfully inserted {len(articles_to_add)} articles into {path}!")
